import json
R,C=22,26
g=[[0]*C for _ in range(R)]
def rect(r0,r1,c0,c1,color):
    for c in range(c0,c1+1): g[r0][c]=g[r1][c]=color
    for r in range(r0+1,r1): g[r][c0]=g[r][c1]=color
# frame 1, interior 4x7; checker color 4
rect(1,6,3,11,1)
for r in range(2,6):
    for c in range(4,11):
        if (r-2+c-4)%2==0: g[r][c]=4
# frame 2, interior 2x2; checker color 8
rect(10,13,2,5,2)
for r in range(11,13):
    for c in range(3,5):
        if (r-11+c-3)%2==0: g[r][c]=8
# frame 3, interior 6x9; checker color 5
rect(9,16,11,21,3)
for r in range(10,16):
    for c in range(12,21):
        if (r-10+c-12)%2==0: g[r][c]=5
print(json.dumps(g,separators=(',',':')))
print('dims',len(g),len(g[0]),'interior counts',sum(v==4 for row in g for v in row),sum(v==8 for row in g for v in row),sum(v==5 for row in g for v in row))
